#include <bits/stdc++.h>
using namespace std;

long long pow_mod(long long base, int exp, int mod) {
    long long result = 1;
    long long b = base % mod;
    for (int i = 0; i < 64; i++) {
        if (((exp >> i) & 1) == 1) result = result * b % mod;
        b = b * b % mod;
    }
    return result;
}

long long C(int n, int r, int mod, vector<long long>& fact, vector<long long>& invFact) {
    if (n < 0 || r < 0 || r > n) return 0;
    return fact[n] * invFact[r] % mod * invFact[n - r] % mod;
}

pair<vector<long long>, vector<long long>> precomputeFactorials(int n, int mod) {
    vector<long long> fact(n + 1);
    vector<long long> invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = fact[i - 1] * i % mod;
    }
    long long invNFact = pow_mod(fact[n], mod - 2, mod);
    invFact[n] = invNFact;
    for (int i = n - 1; i >= 0; i--) {
        invFact[i] = invFact[i + 1] * (i + 1) % mod;
    }
    return {fact, invFact};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int mod = 998244353;
    int n;
    long long K;
    cin >> n >> K;
    if (K >= n) {
        cout << 0 << "\n";
        return 0;
    }
    auto [fact, invFact] = precomputeFactorials(n, mod);
    if (K == 0) {
        cout << fact[n] << "\n";
        return 0;
    }
    long long total = 0;
    for (int i = n - K; i >= 1; i--) {
        int sign = (((n - K - i) % 2 == 0) ? 1 : -1);
        long long comb = C(n, i, mod, fact, invFact);
        long long powVal = pow_mod(i, n, mod);
        long long term = comb * powVal % mod;
        if (sign == -1) term = (mod - term) % mod;
        long long comb2 = C(n - i, K, mod, fact, invFact);
        total = (total + term * comb2) % mod;
    }
    total = (total * 2) % mod;
    cout << total << "\n";
    return 0;
}
